/**
 * issue #61: proxy the small set of RUNTIME-AFFINE editor Admin API
 * actions from editor A (design-time, this process) to runner B (live
 * execution runtime + Temporal) - manual Inject, Debug enable/disable, and
 * live Context inspection/delete. Stock Node-RED serves these from the
 * same process that is executing the flow; in our split A/B topology the
 * live node/state these actions touch only exists on B.
 *
 * This is intentionally NOT a generic reverse proxy: only the exact
 * allow-listed stock routes below are ever forwarded. Everything else
 * (`/flows`, `/nodes`, `/settings`, `/debug/view/*`, unknown paths, ...)
 * falls through to editor A's own local Admin API via `next()`.
 *
 * Allow-list (see `@node-red/nodes/core/common/20-inject.js`,
 * `@node-red/nodes/core/common/21-debug.js` and
 * `@node-red/editor-api/lib/admin/index.js` for the stock routes/
 * permission names this mirrors):
 *
 *   POST   /inject/:id            inject.write
 *   POST   /debug/enable          debug.write
 *   POST   /debug/disable         debug.write
 *   POST   /debug/:id/enable      debug.write
 *   POST   /debug/:id/disable     debug.write
 *   GET    /context/...           context.read
 *   DELETE /context/...           context.write
 *
 * Security boundary: the browser is authenticated/authorized against A.
 * For every allow-listed route we run A's OWN existing
 * `@node-red/editor-api` `auth.needsPermission(<permission>)` middleware
 * first; only once THAT succeeds do we proxy to B, using the configured B
 * bearer token (never the browser's A token). No permission logic is
 * reimplemented here.
 */

"use strict";

const DEBUG_STATE_RE = /^(enable|disable)$/;

/**
 * Pure allow-list matcher: `(method, pathname) -> permission name | null`.
 * No I/O, no Express dependency - kept separate so it can be exhaustively
 * unit tested on its own.
 *
 * @param {string} method - HTTP method, any case.
 * @param {string} pathname - request path WITHOUT query string (e.g.
 *   Express's `req.path`).
 * @returns {string|null} the A-side permission required to proxy this
 *   request, or `null` if the route is not in the allow-list (caller must
 *   fall through to `next()`).
 */
function matchRuntimeAdminRoute(method, pathname) {
    if (typeof pathname !== "string" || !pathname) {
        return null;
    }
    const m = String(method || "").toUpperCase();
    // Normalise away a single trailing slash (but keep root "/" as-is).
    const path = pathname.length > 1 && pathname.endsWith("/") ? pathname.slice(0, -1) : pathname;
    const segments = path.split("/").filter(Boolean);

    if (m === "POST" && segments[0] === "inject" && segments.length === 2 && segments[1]) {
        return "inject.write";
    }

    if (m === "POST" && segments[0] === "debug") {
        // Never proxy the Debug sidebar's static view assets.
        if (segments[1] === "view") {
            return null;
        }
        if (segments.length === 2 && DEBUG_STATE_RE.test(segments[1])) {
            // /debug/enable or /debug/disable
            return "debug.write";
        }
        if (segments.length === 3 && segments[1] && DEBUG_STATE_RE.test(segments[2])) {
            // /debug/:id/enable or /debug/:id/disable
            return "debug.write";
        }
        return null;
    }

    if (segments[0] === "context" && segments.length >= 2) {
        if (m === "GET") {
            return "context.read";
        }
        if (m === "DELETE") {
            return "context.write";
        }
        return null;
    }

    return null;
}

/**
 * Lazily resolves the real, existing `@node-red/editor-api` Admin auth
 * middleware factory. Lazy so unit tests never need `@node-red/editor-api`
 * to be resolvable/initialised, and so a missing/uninitialised auth module
 * fails loudly only when an allow-listed route is actually hit.
 * @returns {function(string): function} `needsPermission(permission)` ->
 *   Express middleware, exactly as used by the stock Inject/Debug/Context
 *   routes it mirrors.
 */
function resolveDefaultNeedsPermission() {
    // eslint-disable-next-line global-require
    const editorApi = require("@node-red/editor-api");
    if (!editorApi || !editorApi.auth || typeof editorApi.auth.needsPermission !== "function") {
        throw new Error("remoteRuntimeAdminProxy: @node-red/editor-api does not expose auth.needsPermission");
    }
    return editorApi.auth.needsPermission;
}

/**
 * Reads the raw (unparsed) request body into a single Buffer. This
 * middleware is intended to run in `settings.httpAdminMiddleware`, which
 * Node-RED's editor-api mounts BEFORE `body-parser` - so the request
 * stream is still untouched here, which is exactly what we want: the
 * Inject/Debug/Context request bytes are forwarded to B byte-for-byte,
 * never interpreted.
 * @param {import('express').Request} req
 * @returns {Promise<Buffer>}
 */
function readRawBody(req) {
    return new Promise((resolve, reject) => {
        if (req.readableEnded || req._body) {
            // Body already consumed upstream (e.g. body-parser ran first
            // in some non-default wiring) - nothing left to forward.
            resolve(Buffer.alloc(0));
            return;
        }
        const chunks = [];
        req.on("data", (chunk) => chunks.push(chunk));
        req.on("end", () => resolve(Buffer.concat(chunks)));
        req.on("error", reject);
    });
}

/**
 * Forwards one already-authorized request to runner B and mirrors its
 * response back to the browser untouched (status, content-type, body).
 * @param {import('express').Request} req
 * @param {import('express').Response} res
 * @param {object} opts
 * @param {string} opts.target - B's base URL, no trailing slash.
 * @param {string} [opts.token] - B bearer token, never the browser's A token.
 * @param {function} opts.fetchImpl
 */
async function forwardToRunner(req, res, opts) {
    const { target, token, fetchImpl } = opts;
    let body;
    try {
        body = await readRawBody(req);
    } catch (err) {
        res.status(502).json({ error: "failed to read request body for runtime proxy" });
        return;
    }

    const headers = {};
    const contentType = req.get("content-type");
    if (contentType) {
        headers["content-type"] = contentType;
    }
    // Outbound Authorization is determined ONLY from the configured B
    // token - the browser's A token is never forwarded.
    if (token) {
        headers.authorization = `Bearer ${token}`;
    }

    let response;
    try {
        response = await fetchImpl(`${target}${req.originalUrl}`, {
            method: req.method,
            headers,
            body: body && body.length ? body : undefined
        });
    } catch (err) {
        res.status(502).json({ error: `runtime runner unavailable: ${err && err.message ? err.message : err}` });
        return;
    }

    const buffer = Buffer.from(await response.arrayBuffer());
    const responseContentType = response.headers && typeof response.headers.get === "function"
        ? response.headers.get("content-type")
        : undefined;
    if (responseContentType) {
        res.set("content-type", responseContentType);
    }
    res.status(response.status).send(buffer);
}

/**
 * Creates the Express-compatible middleware to install as (part of)
 * editor A's `settings.httpAdminMiddleware`.
 *
 * @param {object} remoteRunner - the SAME shared config object used for
 *   `createRemoteDeployStorage` (issue #39) - there must not be separate
 *   target/token configuration for Deploy vs runtime actions.
 * @param {string} remoteRunner.target - runner B's base Admin API URL.
 * @param {string} [remoteRunner.token] - optional bearer token for B. If
 *   not configured, today's unauthenticated/local-runner behaviour is
 *   preserved (still proxies, just without an Authorization header).
 * @param {object} [options] - test/DI seams; production callers should
 *   never need these.
 * @param {function} [options.fetch] - injectable `fetch`. Defaults to the
 *   global `fetch` (Node >=18).
 * @param {function} [options.needsPermission] - injectable
 *   `(permission) => middleware(req,res,next)` factory. Defaults to the
 *   REAL `@node-red/editor-api` `auth.needsPermission` - production code
 *   must not reimplement permission logic.
 * @returns {function} Express middleware `(req, res, next)`.
 */
function createRemoteRuntimeAdminProxy(remoteRunner, options) {
    if (!remoteRunner || !remoteRunner.target) {
        throw new Error("remoteRuntimeAdminProxy requires remoteRunner.target (the remote node-red-temporal runner's base URL)");
    }
    const target = String(remoteRunner.target).replace(/\/+$/, "");
    const token = remoteRunner.token;
    options = options || {};
    const fetchImpl = options.fetch || (typeof fetch === "function" ? fetch : undefined);
    if (typeof fetchImpl !== "function") {
        throw new Error("remoteRuntimeAdminProxy requires a global fetch implementation (Node >=18) or an injected options.fetch");
    }
    const needsPermission = options.needsPermission || resolveDefaultNeedsPermission();

    return function remoteRuntimeAdminProxy(req, res, next) {
        const permission = matchRuntimeAdminRoute(req.method, req.path);
        if (!permission) {
            next();
            return;
        }

        const authMiddleware = needsPermission(permission);
        authMiddleware(req, res, function onAuthorized() {
            forwardToRunner(req, res, { target, token, fetchImpl }).catch(function onProxyError(err) {
                if (!res.headersSent) {
                    res.status(502).json({ error: `runtime proxy failed: ${err && err.message ? err.message : err}` });
                }
            });
        });
    };
}

module.exports = {
    createRemoteRuntimeAdminProxy,
    matchRuntimeAdminRoute
};
